/// transaction's own proposal, impact simulation, owner-answered Human Gate and approval. Never merges/extends an
/// existing floor: every caller passes the COMPLETE intended rule set (onboarding derives it fresh each time; a
/// reclassification proposal carries the current floor with its change applied), so this always starts a fresh
/// record. `operation` is the T2 seal's own operation tag (`"init"`/`"adopt"`/the CIT's own
/// `cit execute <id>: reclassify_adoption_floor` tag). `authorizing_cit` is `Some(id)` only from the
/// `reclassify_adoption_floor` route (onboarding's own first write predates any transaction — see `bound_cit`'s
/// own doc below).
///
/// **A no-op when `rules` is empty** (a repository whose native layout needed no rules beyond the kernel template's
/// own — nothing derived from `spec/**`/`governance/**`/`product/**`/`docs/**` alone, or a bare project with no
/// top-level directory carrying recognised source at all). [`governance/registry/`][PROJECT_ADOPTION_FLOOR_PATH] is
/// OS-managed, non-rebuildable territory (`OS_STORES`, BC-P2-31): the update/rollback snapshot machinery
/// (`update.rs`'s `SNAPSHOT_DIRS`) restores that directory's presence or absence exactly as it found it, so writing
/// an empty, informationless record into it would leave a file behind that a rollback correctly restoring an
/// EARLIER release's layout (one that never created the directory at all) would then have no way to reconcile
/// against. An absent floor file already reads as "no floor recorded" ([`read_project_adoption_floor`]) — the same
/// state as never having called this at all.
pub fn write_project_adoption_floor(
    root: &Path,
    rules: &[Value],
    operation: &str,
    authorizing_cit: Option<&str>,
) -> Result<()> {
    if rules.is_empty() {
        return Ok(());
    }
    let path = root.join(PROJECT_ADOPTION_FLOOR_PATH);
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    // AR84-C3 / AR86-C1-C4: bind this record to the repository and checkout it was derived FOR, inside the
    // document itself, so the EXISTING content MAC (t2::seal_value, which already covers every field here in
    // full) also authenticates identity -- never a seal-format change (`t2::mac_message` is untouched; OD-P2-08
    // §1/§6 forbid reopening that). Bound to this repository's git LINEAGE (see `repository_lineage_id`'s own doc
    // for why not the filesystem path) AND, since lineage alone is a public, adversary-reproducible value
    // (AR86-C1/C2), to this checkout's own local identity-and-sequence anchor, now held in the machine's own
    // protected state (see `FloorIdentity`'s own doc for what it authenticates and why it lives outside the
    // project entirely, P2-AR-0089). See `read_project_adoption_floor`'s own doc for what each half closes.
    let (project_identity, floor_sequence) = FloorIdentity::advance(root)?;
    let mut doc = json!({
        "schema_version": "1.1.0",
        "derived_at": crate::util::now_iso(),
        "bound_repository_lineage": repository_lineage_id(root),
        "bound_project_identity": project_identity,
        "floor_sequence": floor_sequence,
        "floor": rules,
    });
    // **P2-AR-0089, OD-P2-08 §5's OTHER option, recorded here as provenance alongside FloorIdentity -- see
    // `read_project_adoption_floor`'s own doc for how it is gated on read since P2-AR-0091.** When this write is the
    // `reclassify_adoption_floor` CIT-E route, `bound_cit` names the SPECIFIC transaction that authorised it: a
    // value that is *particular* (this one committed change, not "some gov operation") and *ordered* (the record
    // store's own id sequence) in exactly the way `cit::binding` already binds a CIT's own content, impact and
    // writes -- reused, not reinvented. Onboarding's own first write has no transaction to name (change control
    // does not exist yet for a project that has not finished being adopted), so it is absent there, exactly as
    // before this field existed.
    if let Some(cit) = authorizing_cit {
        doc["bound_cit"] = json!(cit);
    }
    crate::t2::seal_value(&mut doc, "", operation)?;
    crate::util::write_json(&path, &doc)?;
    // AR86-C6: this checkout just authored this exact rule set, under change control (onboarding, or a
    // `reclassify_adoption_floor` CIT the owner already approved) -- remember it immediately, without waiting for
    // a later successful read, so it is available to the reconstruction fallback even if this process exits before
    // ever reading the floor back.
    FloorIdentity::remember_rules(root, rules);
    Ok(())
}


/// **P2-HO-0060 §2 (P2-AR-0096) — replaces `reanchor_project_identity`, deleted whole.** Does this checkout hold
/// its own authenticated anchor — the local ledger [`FloorIdentity::advance`] mints and updates — for its CURRENT
/// canonical path? `init`/`adopt` (see their own call sites) read this to decide whether the adoption transaction
/// must re-run even though `governance/framework.lock` already exists: `already_installed` alone can no longer be
/// trusted to mean "this checkout's floor is already anchored", because an ordinary relocation (`mv`/`git mv` of
/// the whole project) copies `framework.lock` along with everything else while leaving the anchor behind, keyed as
/// it is by the OLD canonical path in the machine's own protected store (outside every project,
/// [`FloorIdentity`]'s own doc).
///
/// **Never treats "no anchor is even possible here" as "needs re-onboarding".** [`FloorIdentity::path`] itself
/// returns `None` for two reasons that must NOT trigger a fresh write: inside an OS-created health sandbox (by
/// design — a sandbox's own byte-copied floor is disposable and needs no anchor of its own), and when the
/// protected state root cannot be resolved at all (an SRR/Level-1 concern this module does not own). Only when
/// [`FloorIdentity::path`] resolves to an addressable location — a genuine, ordinary checkout — does an absent
/// local ledger mean what `init`/`adopt` need it to mean: "re-onboard here."
pub fn has_local_adoption_anchor(root: &Path) -> bool {
    match FloorIdentity::path(root) {
        None => true,
        Some(_) => FloorIdentity::read(root).is_some(),
    }
}

/// **P2-HO-0060 §3 (P2-AR-0096).** The additive union of every rule set this MACHINE has ever authenticated for
/// ANY checkout it has minted an identity for, restricted to patterns `fresh` (the native derivation `init`/
/// `adopt` just computed for THIS checkout, from ITS repository's current on-disk shape) does not already cover —
/// the exact AR86-C6 shape `policy::PolicySet::load`'s reconstruction fallback already applies to one checkout's
/// own [`last_known_adoption_floor_rules`], generalised here to EVERY entry the store holds, because a
/// re-onboarding checkout (this function's only caller: `init`/`adopt`, exactly when [`has_local_adoption_anchor`]
/// is `false`) has none of its own yet — that is the whole reason it is re-onboarding. See
/// `RESEARCH/P2-HISTORICAL-RULE-SOURCE.md` for why this protected machine state (never the project document,
/// OD-P2-08 §2) is the proof-grade source, and for why the union is safe unconditionally: it can only ADD a
/// pattern the fresh derivation did not already classify, never displace one it did, so the fresh derivation
/// always wins on conflict and no class already covered is ever widened by this function.
///
/// **Deliberately not applied to a genuinely first-ever `gov init`/`gov adopt`.** A brand-new project has no prior
/// relocation to defend against and nothing of its own in the store yet to protect; unioning in unrelated
/// projects' patterns there would be pure cost (importing common layout names such as `src/**`/`tests/**` into a
/// project that never had them) with no matching security benefit — see the research doc's own "cost to name".
/// Callers gate on this: apply the union only inside the branch [`has_local_adoption_anchor`] returns `false` for
/// an ALREADY-installed checkout (relocated re-onboarding), never for a plain `!already_installed` first install.
///
/// A plain directory scan, never indexed — the same store [`other_live_claim`] already scans, and no larger: one
/// entry per checkout this machine has ever onboarded. Sorted so the result does not depend on directory-listing
/// order (`std::fs::read_dir` makes no ordering guarantee). Takes no `root`/checkout parameter at all: unlike
/// [`other_live_claim`] it does not look anything up BY identity or path — it enumerates every entry
/// unconditionally, so there is nothing checkout-specific to key the scan by. (Callers never reach it for a
/// sandboxed checkout in the first place — see [`has_local_adoption_anchor`]'s own doc — so it does not need to
/// re-check that either.)
pub fn union_last_known_rules_across_store(fresh: &[Value]) -> Vec<Value> {
    let mut merged = fresh.to_vec();
    let mut seen: std::collections::BTreeSet<String> = merged
        .iter()
        .filter_map(|r| r.get("pattern").and_then(|v| v.as_str()).map(str::to_string))
        .collect();
    let Ok(state_root) = crate::srr::state::resolve_state_root() else {
        return merged;
    };
    let dir = state_root.join("adoption-floors");
    let Ok(entries) = std::fs::read_dir(&dir) else {
        return merged;
    };
    let mut paths: Vec<PathBuf> = entries.filter_map(|e| e.ok()).map(|e| e.path()).collect();
    paths.sort();
    for entry in paths {
        let Ok(v) = crate::util::read_json(&entry.join("identity.json")) else {
            continue;
        };
        let Some(state) = parse_floor_identity_state(&v) else {
            continue;
        };
        for r in state.last_known_rules {
            let Some(p) = r.get("pattern").and_then(|v| v.as_str()).map(str::to_string) else {
                continue;
            };
            if seen.insert(p) {
                merged.push(r);
            }
        }
    }
    merged
}

